function buildQuickTakeaways(definition) {
  return [
    `Use ${definition.title.toLowerCase()} to ${definition.promise}.`,
    `${definition.sections[0][0]} is the first pattern to compare with real behavior before you judge the score.`,
    'The calculator result is most useful when the written explanation gives you a specific conversation to have.',
  ];
}

function buildExampleScenarios(definition) {
  const scenarioByCategory = {
    'learn-astrology': 'A pair gets a score that feels accurate, but they want to know which birth-date signal shaped the reading.',
    seasonal: 'Someone wants timing guidance without letting the calendar overrule consent, readiness, or real-life context.',
    numerology: 'A reader is comparing life path themes with the way a partner actually handles independence, care, change, and repair.',
    relationships: 'A user wants to talk about a match result without ranking people, shaming anyone, or treating the score as fate.',
  };

  return [
    {
      title: `When ${definition.topic} appears in a result`,
      body: `${scenarioByCategory[definition.category] || scenarioByCategory.relationships} Start with the section on ${definition.sections[0][0].toLowerCase()}, then ask whether that pattern shows up in daily behavior.`,
    },
    {
      title: 'When the result feels incomplete',
      body: `Use the score as a first layer, then add what the calculator cannot see: shared history, current stress, values, emotional effort, and whether both people are willing to communicate clearly.`,
    },
  ];
}

function buildComparisonRows(definition) {
  return [definition.sections[0], definition.sections[2], definition.sections[4]].map(([heading], index) => ({
    label: heading,
    bestUse: `Use this when you need a practical lens for ${definition.topic}, especially after reading the calculator explanation.`,
    watchOut: index === 0
      ? 'Do not turn the first signal into the whole story.'
      : 'Do not ignore real behavior, consent, timing, or emotional maturity.',
  }));
}

function buildFaq(definition) {
  return [
    {
      question: `Is ${definition.title.toLowerCase()} a prediction?`,
      answer: 'No. It is a reflection guide that gives language for relationship patterns, not a promise about what will happen.',
    },
    {
      question: 'How should I use this with the calculator?',
      answer: `Run the calculator first, then return to this guide and compare the explanation with the sections about ${definition.topic}.`,
    },
    {
      question: 'What if the article does not match real life?',
      answer: 'Trust real behavior first. Symbolic systems are useful prompts, but they should never replace direct experience and clear communication.',
    },
  ];
}

function buildSection(definition, section, index) {
  const [heading, body] = section;
  const readingNotes = [
    `Use this point as a reality check for ${definition.topic}: does it describe the way people communicate, repair tension, make plans, or ask for closeness?`,
    `The useful question is not whether the label sounds impressive. The useful question is whether this pattern helps someone talk with more honesty and less guessing.`,
    `If this theme matches the relationship, turn it into one clear next step: ask a better question, name a need, or adjust an expectation.`,
    `If it does not match, keep the context. A birth-date reading cannot see growth, stress, shared values, or the choices people make after the score appears.`,
    `This is where the article should become practical. Compare the symbolic pattern with real examples instead of using it as a final answer.`,
  ];

  return `
    <h2>${index + 1}. ${heading}</h2>
    <p>${body}</p>
    <p>${readingNotes[index % readingNotes.length]}</p>
  `;
}

function buildContent(definition) {
  const sections = definition.sections.map((section, index) => buildSection(definition, section, index)).join('');
  let content = `
    <h1>${definition.title}</h1>
    <p>${definition.intro}</p>
    <p>This guide is written for people who want to ${definition.promise}. It keeps the language grounded because compatibility tools are most helpful when they create better questions, not when they pretend to know a whole relationship from one data point. Use the ideas below as a structured reflection before you run a calculator result, after you read one, or when you want to compare what the score says with what you already know from real life.</p>
    ${sections}
    <h2>How to use this on Match by Birth</h2>
    <p>Start with a free compatibility result, then come back to this guide and look for the themes that match the explanation. If you are comparing two people, focus on the pair score and the written breakdown. If you are comparing a group, look at every pair because group dynamics are built from many smaller relationships. The most useful reading is the one that helps you talk more clearly, set better expectations, or notice a pattern you were already feeling.</p>
    <h2>Responsible takeaway</h2>
    <p>${definition.topic} should stay human. A score can highlight chemistry, tension, timing, or complementary strengths, but it cannot measure kindness, consent, accountability, or emotional maturity. Let the result support better reflection, then give real behavior the final word. For a private starting point, try the <a href="https://matchbybirth.com">Match by Birth compatibility calculator</a> and read the score as a conversation starter, not a verdict.</p>
  `;

  if (articleWordCount(content) < 700) {
    content += `
      <h2>Practical example</h2>
      <p>Imagine two people read this guide after getting a compatibility score that feels partly accurate and partly surprising. Instead of arguing with the number, they choose one theme from the article and compare it with real moments: how they make plans, how quickly they answer emotional questions, how they repair tension, and whether both people feel respected. That kind of example keeps the reading specific enough to help without pretending the calculator can see every part of the relationship.</p>
      <p>A second useful step is to turn the theme into a small experiment. If the article points to communication, schedule a calmer check-in. If it points to timing, slow the pace before making a bigger promise. If it points to independence, agree on what space looks like in practice. This makes the guide more useful than a label because it connects the symbolic pattern to one observable change.</p>
    `;
  }

  if (articleWordCount(content) < 700) {
    throw new Error(`Article "${definition.slug}" is shorter than 700 words.`);
  }

  return content;
}

const adsenseGrowthPosts = articleDefinitions.map((definition) => {
  const upgrade = PILLAR_ARTICLE_UPGRADES[definition.slug] || {};

  return {
    slug: definition.slug,
    title: definition.title,
    date: definition.date,
    description: definition.description,
    tags: definition.tags,
    category: definition.category,
    relatedSlugs: RELATED_BY_SLUG[definition.slug],
    quickTakeaways: upgrade.quickTakeaways || buildQuickTakeaways(definition),
    exampleScenarios: upgrade.exampleScenarios || buildExampleScenarios(definition),
    comparisonRows: upgrade.comparisonRows || buildComparisonRows(definition),
    faq: upgrade.faq || buildFaq(definition),
    content: upgrade.content || buildContent(definition),
  };
});

export { articleDefinitions };
export default adsenseGrowthPosts;
